const input = $input.first().json;
const errors = [];

// Validate jobId
const jobId = input.jobId;
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!jobId || !uuidRe.test(jobId)) {
  errors.push('Invalid or missing jobId: must be a UUID');
}

// Validate assetType
const assetType = input.assetType;
const ALLOWED = ['scene','narration','captions','manifest','video','thumbnail','render_log','error_log'];
if (!assetType || ALLOWED.indexOf(assetType) === -1) {
  errors.push('Invalid or missing assetType. Allowed: ' + ALLOWED.join(', '));
}

// Validate sceneIndex for scene type
let sceneIndex = input.sceneIndex;
if (assetType === 'scene') {
  if (sceneIndex === undefined || sceneIndex === null) {
    errors.push('sceneIndex required for assetType "scene"');
  } else {
    sceneIndex = Number(sceneIndex);
    if (!Number.isInteger(sceneIndex) || sceneIndex < 1 || sceneIndex > 999) {
      errors.push('sceneIndex must be an integer between 1 and 999');
    }
  }
}

if (errors.length > 0) {
  return [{ json: { valid: false, errors } }];
}

return [{ json: { valid: true, jobId, assetType, sceneIndex } }];

const data = $('Validate Input').first().json;
if (!data.valid) {
  return [{ json: { success: false, errors: data.errors } }];
}

const jobId = data.jobId;
const assetType = data.assetType;
const ASSET_MAP = {
  scene:      { filename: 'scene-{NN}.png' },
  narration:  { filename: 'narration.wav' },
  captions:   { filename: 'captions.ass' },
  manifest:   { filename: 'render-manifest.json' },
  video:      { filename: 'final.mp4' },
  thumbnail:  { filename: 'thumbnail.jpg' },
  render_log: { filename: 'render.log' },
  error_log:  { filename: 'error.log' }
};

let filename;
if (assetType === 'scene') {
  const idx = String(data.sceneIndex).padStart(2, '0');
  filename = 'scene-' + idx + '.png';
} else {
  filename = ASSET_MAP[assetType].filename;
}

const path = '/data/jobs/' + jobId + '/' + filename;

// Reject traversal (belt-and-suspenders)
if (path.indexOf('..') !== -1 || (path.split('/').length - 1) > 4) {
  return [{ json: { success: false, errors: ['Path traversal detected'] } }];
}

return [{ json: { success: true, jobId, assetType, localPath: path, filename } }];
